if(!defined('sugarEntry')||!sugarEntry)die('Invalid entry');
function hrUiEscape($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function hrUiUrl($entry,$query=[]) {return rtrim(getenv('CRM_URL'),'/').'/legacy/index.php?'.http_build_query(['entryPoint'=>$entry]+$query);}
function hrUiGuide($topic) {return hrUiUrl('HrGuide').'#'.$topic;}
