 $paths=['home'=>'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z','people'=>'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0','documents'=>'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6','templates'=>'M3 3h18v18H3zM3 9h18M9 9v12','awards'=>'M8 14l-2 8 6-3 6 3-2-8M17 8a5 5 0 1 1-10 0 5 5 0 0 1 10 0','service'=>'M3 7h18v14H3zM8 7V3h8v4M3 12h18M10 12v3h4v-3','education'=>'M2 9l10-6 10 6-10 6zM6 12v6c4 3 8 3 12 0v-6M22 9v9','relatives'=>'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M16 9h6M19 6v6','audit'=>'M12 3l8 4v6c0 5-8 9-8 9s-8-4-8-9V7zM8 12l3 3 5-5','guide'=>'M4 3h7v18H4zM11 3h9v18h-9M7 7h1M14 7h3M14 11h3','menu'=>'M3 6h18M3 12h18M3 18h18','logout'=>'M9 21H4V3h5M14 7l5 5-5 5M8 12h13','settings'=>'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2','search'=>'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0'];
