function hrUiNav($active) {
 global $current_user;$base=rtrim(getenv('CRM_URL'),'/');
 $items=['home'=>['Обзор',$base.'/#/home',null],'people'=>['Сотрудники',$base.'/#/HR_People/index','HR_People'],'documents'=>['Документы',$base.'/#/HR_Documents','HR_People'],'templates'=>['Шаблоны',$base.'/#/HR_Templates',null],'awards'=>['Награды',$base.'/#/HR_Awards/index','HR_Awards'],'service'=>['Служба',$base.'/#/HR_Service/index','HR_Service'],'education'=>['Образование',$base.'/#/HR_Education/index','HR_Education'],'relatives'=>['Родственники',$base.'/#/HR_Relatives/index','HR_Relatives'],'audit'=>['Аудит',$base.'/#/HR_Audit/index','HR_Audit'],'guide'=>['Инструкции',$base.'/#/HR_Help',null]];
 $role=$current_user->isAdmin()?'Администратор':(BeanFactory::newBean('HR_People')->ACLAccess('edit')?'Кадровик':'Просмотр');
 echo '<aside class="hr-sidebar"><div class="hr-brand"><span class="hr-brand-symbol">'.hrUiIcon('people').'</span><div><strong>Кадровый контур</strong><small>Сотрудники и документы</small></div></div><span class="hr-nav-caption">Рабочее пространство</span><nav class="hr-nav" aria-label="Кадровые разделы">';
 foreach($items as $key=>[$label,$url,$module]){if($module&&!BeanFactory::newBean($module)->ACLAccess('list'))continue;echo '<a target="_top" data-section="'.$key.'" href="'.hrUiEscape($url).'"'.($key===$active?' aria-current="page"':'').'>'.hrUiIcon($key).'<span>'.hrUiEscape($label).'</span></a>';}
 echo '</nav><div class="hr-sidebar-footer"><span class="hr-avatar">'.hrUiEscape(mb_strtoupper(mb_substr($current_user->user_name,0,1))).'</span><div><strong>'.hrUiEscape($current_user->user_name).'</strong><small>'.hrUiEscape($role).'</small></div></div></aside><div class="hr-backdrop"></div>';
 echo '<header class="hr-topbar"><div class="hr-topbar-title"><button class="hr-menu-button" data-hr-menu aria-label="Открыть меню" aria-expanded="false">'.hrUiIcon('menu').'</button><span>Кадровое рабочее место</span></div><div class="hr-appearance"><button type="button" class="hr-logout-button" data-hr-logout aria-label="Выйти из аккаунта">'.hrUiIcon('logout').'<span>Выйти</span></button><a target="_top" href="'.hrUiEscape($base.'/#/HR_Documents').'" aria-label="Поиск сотрудника для документа">'.hrUiIcon('search').'</a><button type="button" class="hr-settings-button" data-hr-settings-toggle aria-label="Настройки оформления" aria-expanded="false" aria-controls="hr-appearance-panel">'.hrUiIcon('settings').'</button><div id="hr-appearance-panel" class="hr-appearance-panel" hidden><strong>Оформление</strong><label>Тема<select aria-label="Тема оформления" data-hr-setting="theme"><option value="system">Системная</option><option value="light">Светлая</option><option value="dark">Тёмная</option></select></label><label>Акцентный цвет<select aria-label="Акцентный цвет" data-hr-setting="accent"><option value="blue">Синий</option><option value="emerald">Изумруд</option><option value="violet">Фиолетовый</option></select></label><label>Плотность таблиц<select aria-label="Плотность таблиц" data-hr-setting="density"><option value="comfortable">Обычная</option><option value="compact">Компактная</option></select></label></div></div></header>';
}
function hrUiStyle(){echo '<style>'.file_get_contents('/opt/hr/ui.css').'</style><script>'.file_get_contents('/opt/hr/ui.js').'</script>';}
function hrUiListHeader($module){
 $titles=['HR_Awards'=>['Награды','Добавить награду','awards'],'HR_Service'=>['Периоды службы','Добавить период службы','service'],'HR_Education'=>['Образование','Добавить образование','education'],'HR_Relatives'=>['Родственники','Добавить родственника','relatives']];
 [$title,$action,$section]=$titles[$module];hrUiStyle();echo '<main class="hr-shell">';hrUiNav($section);echo '<h1>'.hrUiEscape($title).'</h1><p class="hr-hint">Каждая запись связана с сотрудником. Нажмите на название, чтобы посмотреть или изменить сведения.</p><div class="hr-actions">';
 if(BeanFactory::newBean($module)->ACLAccess('edit'))echo '<a class="hr-button" target="_top" href="'.hrUiEscape(rtrim(getenv('CRM_URL'),'/').'/legacy/index.php?module='.$module.'&action=EditView').'">'.hrUiEscape($action).'</a>';
 echo '<a target="_top" href="'.hrUiEscape(hrUiGuide('related')).'">Инструкция и образец заполнения</a></div>';
}
function hrUiReturnLinks($module='HR_People') {
 $base=rtrim(getenv('CRM_URL'),'/');
 echo '<nav class="hr-actions" aria-label="Возврат"><a class="hr-button secondary" target="_top" href="'.hrUiEscape($base.'/#/'.$module.'/index').'">К списку '.($module==='HR_People'?'сотрудников':'записей').'</a><a class="hr-button secondary" target="_top" href="'.hrUiEscape($base.'/#/home').'">На главную</a></nav>';
 $record=$_REQUEST['record']??'';if(is_string($record)&&preg_match('/^[a-f0-9-]{36}$/Di',$record)&&BeanFactory::newBean('HR_Audit')->ACLAccess('list'))echo '<p><a target="_top" href="'.hrUiEscape(hrUiUrl('HrAudit',['record'=>$record])).'">История изменений этой записи</a></p>';
}
function hrUiRecordHelp($module){
 hrUiReturnLinks($module);
 $topic=$module==='HR_People'?'people':'related';$examples=require '/opt/hr/HrExamples.php';
 echo '<section class="hr-panel"><p>'.($module==='HR_People'?'Заполните ФИО и нужные кадровые сведения. Руководитель выбирается из существующих сотрудников.':'Создайте отдельную запись и укажите сотрудника, к которому она относится.').'</p><a href="'.hrUiEscape(hrUiGuide($topic)).'">Пошаговая инструкция</a>';
 if(isset($examples[$module])){echo '<details><summary>Пример заполнения</summary><table class="hr-table"><tbody>';foreach($examples[$module] as $label=>$value)echo '<tr><th>'.hrUiEscape($label).'</th><td>'.hrUiEscape($value).'</td></tr>';echo '</tbody></table><p class="hr-hint">Вымышленный образец. Перенесите нужные значения в поля и нажмите Save / Сохранить.</p></details>';}echo '</section>';
}
function hrUiHistory($personId=null){
 $items=[];foreach(glob(hrDir().'/*.json') as $path){$id=pathinfo($path,PATHINFO_FILENAME);if(!preg_match('/^[a-f0-9]{32}$/D',$id))continue;$item=json_decode(file_get_contents($path),true);if(empty($item['person_id'])||($personId&&$item['person_id']!==$personId))continue;$person=BeanFactory::getBean('HR_People',$item['person_id']);if(!$person->id||!$person->ACLAccess('view'))continue;$item['id']=$id;$item['person_name']=$person->name;$item['sort_time']=isset($item['created_at'])?strtotime($item['created_at']):filemtime($path);$items[]=$item;}usort($items,fn($a,$b)=>$b['sort_time']<=>$a['sort_time']);return $items;
}
function hrUiHistoryTable($items){
 echo '<div class="hr-table-wrap"><table class="hr-table"><thead><tr><th>Документ</th><th>Сотрудник</th><th>Создан</th><th>Автор</th><th>Версия</th><th></th></tr></thead><tbody>';
 foreach($items as $item){$title=$item['template_title']??hrTemplates()[$item['template']]??'Документ';$date=isset($item['created_at'])?(new DateTimeImmutable($item['created_at']))->format('d.m.Y H:i'):date('d.m.Y',strtotime($item['snapshot']['generated_at']??'now'));$actor=$item['author_name']??BeanFactory::getBean('Users',$item['author']??'')->user_name??'—';echo '<tr><td>'.hrUiEscape($title).'</td><td>'.hrUiEscape($item['person_name']).'</td><td>'.hrUiEscape($date).'</td><td>'.hrUiEscape($actor).'</td><td>'.((int)($item['revision']??0)+1).'</td><td><a href="'.hrUiEscape(hrUiUrl('HrDocuments',['person'=>$item['person_id'],'document'=>$item['id']])).'">Открыть</a></td></tr>';}
 if(!$items)echo '<tr><td colspan="6" class="hr-empty">Документов пока нет. Выберите сотрудника и сформируйте первый документ.</td></tr>';echo '</tbody></table></div>';
}
